<template>
  <div class="agent-documents index-ignore">
    <button v-for="doc in documents" :key="doc.id" type="button" aria-haspopup="dialog" @click="open(doc)">
      {{ doc.title }}<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 2.5h8l4 4v11H4zM12 2.5v4h4M7 10h6M7 13h6" /></svg>
    </button>
    <Teleport to="body">
      <dialog ref="dialog" class="agent-document-dialog" :aria-label="selected?.title || 'Agent documentation'" @close="onClose" @click="closeBackdrop" @keydown.stop>
        <header class="agent-document-header">
          <div><h2>{{ selected?.title }}</h2><span>{{ selected?.path }}</span></div>
          <button type="button" aria-label="Close document" autofocus @click="close"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="m5 5 10 10M15 5 5 15" /></svg></button>
        </header>
        <div ref="content" class="agent-document-content" tabindex="0" :aria-label="selected?.title">
          <p v-if="loading" role="status">Loading document…</p>
          <div v-else-if="error" role="status"><p>This document could not be loaded.</p><button type="button" @click="load">Try again</button></div>
          <pre v-else>{{ text }}</pre>
        </div>
      </dialog>
    </Teleport>
  </div>
</template>

<script>
import { lockBodyScroll } from '../../utils/bodyScrollLock';
const documents = [
  { id: 'guide', title: 'Reading guide', path: '/agent/guide.txt' },
  { id: 'archive', title: 'Complete public text', path: '/agent/archive.txt' },
  { id: 'api', title: 'API reference', path: '/agent/openapi.json' },
];
export default {
  data: () => ({ documents, selected: null, loading: false, error: false, text: '' }),
  beforeUnmount() { this._request?.abort(); this._release?.(); this.$refs.dialog?.close(); },
  methods: {
    async open(doc) {
      this._trigger = document.activeElement;
      this.selected = doc;
      this._release ||= lockBodyScroll();
      this.$refs.dialog.showModal();
      await this.load();
    },
    async load() {
      this._request?.abort();
      const request = this._request = new AbortController();
      this.loading = true; this.error = false; this.text = '';
      try {
        const response = await fetch(this.selected.path, { signal: request.signal });
        if (!response.ok) throw new Error('Document unavailable');
        const text = await response.text();
        if (!request.signal.aborted) this.text = text;
      } catch (error) {
        if (!request.signal.aborted) this.error = true;
      } finally {
        if (!request.signal.aborted) { this.loading = false; this.$refs.content.scrollTop = 0; }
      }
    },
    close() { this.$refs.dialog.close(); },
    closeBackdrop(event) { if (event.target === this.$refs.dialog) this.close(); },
    onClose() {
      this._request?.abort(); this._release?.(); this._release = null;
      this.text = ''; this.selected = null;
      if (this._trigger?.isConnected) this._trigger.focus({ preventScroll: true });
    },
  },
};
</script>

