.agent-document-dialog[open] { display: flex; flex-direction: column; animation: document-enter 180ms ease-out; }
.agent-document-dialog::backdrop { background: rgb(25 24 23 / 30%); backdrop-filter: blur(8px); animation: document-backdrop 180ms ease-out; }
.agent-document-header { display: flex; flex: none; justify-content: space-between; align-items: center; gap: 20px; padding: 20px 26px; border-bottom: 1px solid color-mix(in srgb, currentColor 12%, transparent); }
.agent-document-header h2 { margin: 0; font: 400 22px/1.4 'PT Serif', Georgia, serif; }
.agent-document-header span { display: block; margin-top: 4px; color: var(--site-text-secondary); font: 12px/1.5 ui-monospace, monospace; }
.agent-document-header button { display: grid; place-items: center; flex: none; width: 36px; height: 36px; padding: 8px; border: 0; border-radius: 50%; background: transparent; color: inherit; cursor: var(--site-interactive-cursor, pointer); }
.agent-document-header svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.3; }
.agent-document-content { flex: 1; min-height: 0; padding: 24px 28px; overflow: auto; overscroll-behavior: contain; }
.agent-document-dialog .agent-document-content pre { box-sizing: border-box; width: 100%; margin: 0; padding: 0; background: transparent; color: inherit; white-space: pre-wrap; word-break: normal; overflow-wrap: anywhere; font: 400 13px/1.8 ui-monospace, SFMono-Regular, Consolas, monospace; }
.agent-document-content:focus-visible { outline: 1px solid var(--site-accent); outline-offset: -3px; }
body.dark-mode .agent-document-dialog { --document-paper: #242424; --document-ink: #dedbd6; }
@media (hover: hover) { .agent-documents > button:hover { color: var(--site-accent); }.agent-document-header button:hover { background: color-mix(in srgb, currentColor 7%, transparent); } }
@media (max-width: 600px) { .agent-document-dialog { height: calc(100dvh - 32px); }.agent-document-header { padding: 16px; }.agent-document-header h2 { font-size: 19px; }.agent-document-content { padding: 20px 16px; } }
@keyframes document-enter { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }
@keyframes document-backdrop { from { opacity: 0; } to { opacity: 1; } }
@media (prefers-reduced-motion: reduce) { .agent-document-dialog[open], .agent-document-dialog::backdrop { animation: none; } }
</style>
